// DSiDL - bitmap font tables (generated by tools/mkfont.py)
#ifndef DSIDL_FONT_H
#define DSIDL_FONT_H

#include <stdint.h>

typedef struct {
    uint32_t offset;   // into data[], 4-bit alpha, two pixels per byte
    int8_t x, y;       // bitmap position relative to pen (y from line top)
    uint8_t w, h;
    uint8_t advance;
} font_glyph_t;

typedef struct {
    const font_glyph_t *glyphs;   // code points 32..126 then 160..255
    const unsigned char *data;
    int ascent, descent;
} font_t;

enum { FONT_SMALL, FONT_BODY, FONT_BOLD, FONT_TITLE, FONT_BIG, FONT_COUNT };

extern const font_t fonts[FONT_COUNT];

#endif
